"""Small noninteractive commands whose output does not need the listing engine."""
import os
from pathlib import Path


def list_plugins():
    # In a fresh installation there are no installed plugin binaries.
    root = Path(os.environ.get("XDG_CONFIG_HOME", str(Path.home() / ".config"))) / "lla" / "plugins"
    plugins = sorted(p.stem for p in root.iterdir() if p.is_file() and p.suffix in (".so", ".dll", ".dylib")) if root.exists() else []
    if not plugins:
        print("╭─ Plugins ───────────────────────────────────╮\n│   ℹ  No plugins installed.                  │\n│                                             │\n│      Run lla install --help to get started. │\n╰─────────────────────────────────────────────╯")
    else:
        print("╭─ Plugins ───────────────────────────────────╮")
        for name in plugins:
            print(f"│   • {name:<40}│")
        print("╰─────────────────────────────────────────────╯")
    return 0


def plugin_error(name):
    print(f"\n✗ Plugin Error\n\n  Plugin '{name}' not found.\n  \n  No plugins are currently installed. Run 'lla install' to install plugins.")
    return 1
"""Theme subcommands for the lla-compatible CLI."""
import os
import re
import shutil
import sys
from pathlib import Path


def _theme_dir():
    return Path(os.environ.get("XDG_CONFIG_HOME", str(Path.home() / ".config"))) / "lla" / "themes"


def _err(msg):
    print("\n✗ Error\n\n  " + msg)
    return 1


def run_theme(args):
    """Handle argv following the `theme` word. Return process status."""
    if not args or args[0] in ("-h", "--help", "help"):
        print("executable-theme \nInteractive theme manager\n\nUSAGE:\n    executable theme [SUBCOMMAND]\n\nSUBCOMMANDS:\n    help       Print this message or the help of the given subcommand(s)\n    install    Install theme(s) from a file or directory\n    preview    Preview a theme using sample output\n    pull       Pull and install themes from the official repository")
        return 0
    cmd = args[0]
    if cmd == "preview":
        if len(args) < 2:
            return _err("The following required arguments were not provided:\n    <name>")
        name = args[1].removesuffix(".toml")
        paths = list(_theme_dir().glob("*.toml")) + [Path(name + ".toml")]
        theme = next((p for p in paths if p.is_file() and
                      (p.stem == name or re.search(r"^name\s*=\s*[\"']" + re.escape(name) + r"[\"']", p.read_text(errors="replace"), re.M))), None)
        if theme is None:
            print(f"\n✗ Error\n\n  Theme '{name}' not found. Install it with `lla theme pull` or place it in ~/.config/lla/themes")
            return 1
        # Preview content is normally colorized; keep a stable plain representation.
        raw = theme.read_text(errors="replace")
        title = re.search(r'^name\s*=\s*["\']([^"\']+)', raw, re.M)
        author = re.search(r'^author\s*=\s*["\']([^"\']+)', raw, re.M)
        print(f"Theme preview: {title.group(1) if title else name}")
        if author:
            print(f"Author : {author.group(1)}")
        desc = re.search(r"^(?:description|notes)\s*=\s*[\"']([^\"']+)", raw, re.M)
        if desc:
            print(f"Notes  : {desc.group(1)}")
        print("\nCore palette\n Files       Dirs        Symlinks    Exec        Size        Date       \n\nSample directory listing\nDefault view (lla)\n   src/\n   Cargo.toml\n   scripts/build.sh\n   current -> releases/2025\n   .env\n\nLong view (lla -l)\nPermissions  Size Modified     User Group Name\ndrwxr-xr-x   4.0K Nov 15 10:22 mona staff  src/\n-rw-r--r--   2.4K Nov 14 18:02 mona staff  Cargo.toml\n-rwxr-xr-x   8.8K Nov 13 09:10 mona staff  scripts/build.sh\nlrwxrwxrwx     9B Nov 12 08:01 mona staff  current -> releases/2025\n-rw-r--r--   640B Nov 11 21:58 mona staff  .env\n\nSample search output\nrg --search \"theme\"\nsrc/main.rs:42     let theme = load_theme(name)?;\n         ^^^^\n1 match across 1 file")
        return 0
    if cmd == "install":
        if len(args) < 2:
            return _err("The following required arguments were not provided:\n    <path>")
        src = Path(args[1]).expanduser()
        if not src.exists():
            return _err(f"Theme path does not exist: {src}")
        candidates = [src] if src.is_file() else sorted(src.glob("*.toml"))
        dest = _theme_dir()
        dest.mkdir(parents=True, exist_ok=True)
        count = 0
        for f in candidates:
            if not f.is_file():
                continue
            shutil.copy2(f, dest / f.name)
            print(f"✓ Installed theme: {f.name}")
            count += 1
        if not count:
            return _err("No theme files found")
        print(f"\n{count} theme(s) installed successfully!\nUse lla theme to select a theme")
        return 0
    if cmd == "pull":
        return _err("Unable to pull themes: network access is unavailable")
    return _err(f"Unknown theme subcommand '{cmd}'")
"""Implementation of lla's non-interactive diff subcommand."""
import difflib
import os
import subprocess


def _size(n):
    if n is None:
        return "-"
    if n < 1024:
        return f"{n}B"
    for unit in ("KB", "MB", "GB", "TB"):
        n /= 1024
        if n < 1024 or unit == "TB":
            return f"{n:.1f}{unit}"


def _error(msg):
    print("\n✗ Error\n\n  " + msg)
    return 1


def run_diff(left, right=None, git=False, git_ref="HEAD"):
    left = os.path.abspath(left)
    if not os.path.exists(left):
        return _error(f"Path '{left}' does not exist or is not accessible")
    if git:
        try:
            root = subprocess.check_output(["git", "-C", left if os.path.isdir(left) else os.path.dirname(left), "rev-parse", "--show-toplevel"], stderr=subprocess.DEVNULL, text=True).strip()
        except Exception:
            return _error(f"'{left}' is not inside a git repository")
        rel = os.path.relpath(left, root)
        try:
            raw = subprocess.check_output(["git", "-C", root, "show", f"{git_ref}:{rel}"], stderr=subprocess.DEVNULL)
        except Exception:
            return _error(f"Path '{rel}' does not exist in git reference '{git_ref}'")
        try:
            current = open(left, "rb").read()
            if b"\0" in current or b"\0" in raw:
                return _error("Cannot display diff for binary files")
            old, new = raw.decode(errors="replace").splitlines(True), current.decode(errors="replace").splitlines(True)
            source = f"git:{git_ref}:{rel}"
            print(f"Comparing {source} → {left}")
            delta = len(current) - len(raw)
            pct = delta / len(raw) * 100 if raw else (100.0 if current else 0.0)
            sizedelta = f"{delta:+d}B ({pct:+.1f}%)" if delta else "0B"
            print(f"Summary:\n  Size     {_size(len(raw))} → {_size(len(current))}   {sizedelta}\n  Lines    {len(old)} → {len(new)}   {len(new)-len(old)}\n")
            if raw == current:
                print("No differences found.")
            else:
                print("".join(difflib.unified_diff(old, new, fromfile=source, tofile=left)), end="")
            return 0
        except OSError as e:
            return _error(str(e))
    if right is None:
        return _error("A second path is required unless --git is specified")
    right = os.path.abspath(right)
    if not os.path.exists(right):
        return _error(f"Path '{right}' does not exist or is not accessible")
    if not os.path.isdir(left) and not os.path.isdir(right):
        try:
            a, b = open(left, "rb").read(), open(right, "rb").read()
        except OSError as e:
            return _error(str(e))
        if b"\0" in a or b"\0" in b:
            return _error("Cannot display diff for binary files")
        al, bl = a.decode(errors="replace").splitlines(True), b.decode(errors="replace").splitlines(True)
        delta = len(b) - len(a)
        pct = (delta / len(a) * 100) if a else (100.0 if b else 0.0)
        print(f"Comparing {left} → {right}")
        sizedelta = f"{delta:+d}B ({pct:+.1f}%)" if delta else "0B"
        print(f"Summary:\n  Size     {_size(len(a))} → {_size(len(b))}   {sizedelta}\n  Lines    {len(al)} → {len(bl)}   {len(bl)-len(al)}\n")
        if a == b:
            print("No differences found.")
            return 0
        print("".join(difflib.unified_diff(al, bl, fromfile=left, tofile=right)), end="")
        return 0
    if not os.path.isdir(left) or not os.path.isdir(right):
        kind = "directory" if os.path.isdir(left) else "file"
        return _error(f"Cannot diff {kind} '{left if kind == 'directory' else right}' against {'file' if kind == 'directory' else 'directory'} '{right if kind == 'directory' else left}'")
    def inventory(root):
        found = {}
        for base, dirs, files in os.walk(root):
            dirs.sort(); files.sort()
            for name in files:
                path = os.path.join(base, name)
                found[os.path.relpath(path, root)] = path
        return found
    lfiles, rfiles = inventory(left), inventory(right)
    lnames, rnames = set(lfiles), set(rfiles)
    rows=[]
    for name in sorted(lnames | rnames):
        lp, rp = lfiles.get(name), rfiles.get(name)
        ls = os.path.getsize(lp) if lp else None
        rs = os.path.getsize(rp) if rp else None
        if name not in lnames: status='+'; d=rs or 0
        elif name not in rnames: status='-'; d=-(ls or 0)
        elif ls != rs or os.path.isdir(lp) != os.path.isdir(rp): status='~'; d=(rs or 0)-(ls or 0)
        elif open(lp,'rb').read() != open(rp,'rb').read(): status='~'; d=(rs or 0)-(ls or 0)
        else: continue
        rows.append((status,name,ls,rs,d))
    print(f"Comparing {left} → {right}")
    plus=sum(x[4] for x in rows if x[0]=='+'); minus=sum(-x[4] for x in rows if x[0]=='-')
    added=sum(x[0]=='+' for x in rows); removed=sum(x[0]=='-' for x in rows); changed=sum(x[0]=='~' for x in rows)
    print(f"Summary:\n  Files    {added} added, {removed} removed, {changed} changed\n  Sizes    {_size(plus)} added, {_size(minus)} removed\n  Net      {('+' if plus-minus>=0 else '')}{_size(plus-minus)}")
    if rows:
        adds = [r for r in rows if r[0] == '+']
        dels = [r for r in rows if r[0] == '-']
        if adds:
            r=max(adds,key=lambda x:x[4]); print(f"  Largest+ +{_size(r[4])} {r[1]}")
        if dels:
            r=min(dels,key=lambda x:x[4]); print(f"  Largest- {_size(r[4])} {r[1]}")
    if rows:
        print("\nStatus  Path   Left  Right             Δ\n──────  ─────  ────  ─────  ────────────")
        for s,n,l,r,d in rows:
            perc=f" ({d/l*100:+.1f}%)" if s=='~' and l else ""
            print(f"{s:<6}  {n:<5}  {_size(l):>4}  {_size(r):>5}  {(('+' if d>=0 else '')+_size(d)):>12}{perc}")
    return 0
"}

